```c
// futhark_http_server.c
#include <microhttpd.h>
#include <string.h>
#include <stdlib.h>
#include "molecular_api.h"

struct futhark_context *global_ctx;

static enum MHD_Result handle_request(
    void *cls, struct MHD_Connection *connection,
    const char *url, const char *method,
    const char *version, const char *upload_data,
    size_t *upload_data_size, void **con_cls) {

    if (strcmp(url, "/api/conformers") == 0) {
        // Futhark GPU számítás
        struct futhark_f64_1d *result;
        futhark_entry_main(global_ctx, &result, upload_data);

        // JSON válasz
        const char *response = "{\"status\":\"ok\",\"gpu_processed\":true}";
        struct MHD_Response *mhd_response = 
            MHD_create_response_from_buffer(strlen(response),
                (void*)response, MHD_RESPMEM_PERSISTENT);

        MHD_add_response_header(mhd_response, "Content-Type", "application/json");
        return MHD_queue_response(connection, 200, mhd_response);
    }

    return MHD_NO;
}

int main() {
    struct futhark_context_config *cfg = futhark_context_config_new();
    global_ctx = futhark_context_new(cfg);

    struct MHD_Daemon *daemon = MHD_start_daemon(
        MHD_USE_SELECT_INTERNALLY, 8080, NULL, NULL,
        &handle_request, NULL, MHD_OPTION_END);

    printf("🚀 Futhark GPU API szerver: ");
    getchar();

    MHD_stop_daemon(daemon);
    futhark_context_free(global_ctx);
    return 0;
}
```

