```julia
# HTTP API Server módosítás - add hozzá a fájl végére

module JuliaMolecularAPIServer

using HTTP
using JSON3

function start_api_server(port=8082)
    router = HTTP.Router()

    HTTP.register!(router, "POST", "/api/conformers", handle_conformers)
    HTTP.register!(router, "GET", "/health", handle_health)

    println("✅ Julia Molecular API running on port $port")
    HTTP.serve(router, "0.0.0.0", port)
end

function handle_conformers(req::HTTP.Request)
    try
        data = JSON3.read(IOBuffer(HTTP.payload(req)))
        smiles = data.smiles

        result = Dict(
            "status" => "success",
            "smiles" => smiles,
            "processed" => true
        )

        return HTTP.Response(200, 
            ["Content-Type" => "application/json", "Access-Control-Allow-Origin" => "*"],
            JSON3.write(result))
    catch e
        return HTTP.Response(500,
            ["Content-Type" => "application/json"],
            JSON3.write(Dict("status" => "error", "message" => string(e))))
    end
end

function handle_health(req::HTTP.Request)
    return HTTP.Response(200, JSON3.write(Dict("status" => "ok")))
end

end

# Indítás
JuliaMolecularAPIServer.start_api_server(8082)
