  c1:verified_conformer n -> 
  c2:verified_conformer n -> 
  Lemma (rmsd c1 c2 = rmsd c2 c1)
let rmsd_symmetric c1 c2 = 
  assert (rmsd c1 c2 = sqrt (sum_squares (c1.coords - c2.coords)))

// Energia konzervációs tétel bizonyítva
val energy_conservation:
  mol:molecule n ->
  dt:real{dt > 0.0} ->
  Lemma (total_energy (evolve mol dt) = total_energy mol)
let energy_conservation mol dt =
  calc (=) {
    total_energy (evolve mol dt);
    = { kinetic_energy_lemma mol dt }
    kinetic mol + potential mol;
    = { potential_invariant mol dt }
    total_energy mol;
  }

// Verifikált batch feldolgozás - totális függvény
