use "net"
use "http_server"
use "collections"
use "json"
actor Main
  new create(env: Env) =>
    try
      let auth = env.root as AmbientAuth
      TCPListener(auth, recover HTTPNotify(env) end, "", "8080")
    else
      env.err.print("fail")
    end
class HTTPNotify is TCPListenNotify
  let _env: Env
  new iso create(env: Env) =>
    _env = env
  fun ref listening(listen: TCPListener ref) =>
    _env.out.print("gateway 8080")
  fun ref not_listening(listen: TCPListener ref) =>
    _env.err.print("not listening")
  fun ref connected(listen: TCPListener ref): TCPConnectionNotify iso^ =>
    Conn(_env)
class Conn is TCPConnectionNotify
  let _env: Env
  var _buf: String iso = recover String end
  new iso create(env: Env) =>
    _env = env
  fun ref received(conn: TCPConnection ref, data: Array[U8] iso, times: USize): Bool =>
    _buf.append(consume data)
    let s = _buf.clone()
    if s.contains("\r\n\r\n") then
      let r =
        if s.starts_with("POST /api/conformers") then
          handle_conformers(s)
        elseif s.starts_with("POST /api/gpu/optimize") then
          proxy_json("", s)
        elseif s.starts_with("POST /api/quantum") then
          proxy_json("", s)
        elseif s.starts_with("POST /api/julia") then
          proxy_json("", s)
        elseif s.starts_with("GET /health") then
          ok_json("{\"status\":\"ok\"}")
        elseif s.starts_with("OPTIONS ") then
          options()
        else
          not_found()
        end
      conn.write(r.array())
      conn.dispose()
      false
    else
      true
    end
  fun ref extract_body(req: String): String =>
    let i = try req.find("\r\n\r\n")? + 4 else 0 end
    req.substring(i.isize())
  fun ref ok_json(body: String): String =>
    recover val
      "HTTP/1.1 200 OK\r\nContent-Type: application/json\r\nAccess-Control-Allow-Origin: *\r\nConnection: close\r\nContent-Length: " +
      body.size().string() + "\r\n\r\n" + body
    end
  fun ref not_found(): String =>
    recover val
      "HTTP/1.1 404 Not Found\r\nConnection: close\r\nContent-Length: 0\r\n\r\n"
    end
  fun ref options(): String =>
    recover val
      "HTTP/1.1 200 OK\r\nAccess-Control-Allow-Origin: *\r\nAccess-Control-Allow-Methods: GET, POST, OPTIONS\r\nAccess-Control-Allow-Headers: Content-Type\r\nConnection: close\r\nContent-Length: 0\r\n\r\n"
    end
  fun ref proxy_json(url: String, req: String): String =>
    let body = extract_body(req)
    let client = HTTPClient(_env)
    let res = client.post(url, body, "application/json")
    ok_json(res)
  fun ref handle_conformers(req: String): String =>
    let body = extract_body(req)
    let client = HTTPClient(_env)
    let vres = client.post("", body, "application/json")
    let gres = client.post("", body, "application/json")
    let qres = client.post("", body, "application/json")
    let merged = "{\"status\":\"success\",\"julia\":" + vres + ",\"gpu\":" + gres + ",\"quantum\":" + qres + "}"
    ok_json(merged)
class HTTPClient
  let _env: Env
  new create(env: Env) =>
    _env = env
  fun post(url: String val, body: String val, ctype: String val): String val =>
    let parsed = try URL.parse(url)? else URL("http", "127.0.0.1", "80", "/", "") end
    let host = parsed.host
    let port = parsed.service
    let path = if parsed.path.size() > 0 then parsed.path else "/" end
    let auth = _env.root as AmbientAuth
    let tcp = TCPConnection.active(auth, recover ClientNotify(body, ctype, host, path) end, host, port)
    ClientNotify.wait_for_response(tcp)
class ClientNotify is TCPConnectionNotify
  let _body: String
  let _ctype: String
  let _host: String
  let _path: String
  var _resp: String iso = recover String end
  primitive Store
    fun apply(s: String iso): String iso => s
  new iso create(body: String, ctype: String, host: String, path: String) =>
    _body = body
    _ctype = ctype
    _host = host
    _path = path
  fun ref connected(conn: TCPConnection ref) =>
    let req = "POST " + _path + " HTTP/1.1\r\nHost: " + _host + "\r\nContent-Type: " + _ctype + "\r\nContent-Length: " + _body.size().string() + "\r\nConnection: close\r\n\r\n" + _body
    conn.write(req.array())
  fun ref received(conn: TCPConnection ref, data: Array[U8] iso, times: USize): Bool =>
    _resp.append(consume data)
    true
  fun ref closed(conn: TCPConnection ref) =>
    None
  fun ref connect_failed(conn: TCPConnection ref) =>
    None
  fun ref auth_failed(conn: TCPConnection ref) =>
    None
  fun box response_body(): String val =>
    let s = _resp.clone()
    let i = try s.find("\r\n\r\n")? + 4 else 0 end
    s.substring(i.isize())
  fun ref finish(): String val =>
    this.response_body()
  fun ref timeout(conn: TCPConnection ref) =>
    None
  fun ref throttled(conn: TCPConnection ref) =>
    None
  fun ref unthrottled(conn: TCPConnection ref) =>
    None
  fun ref dispose() =>
    None
  fun ref error(conn: TCPConnection ref, err: (U32, String)) =>
    None
  fun ref expect(): String iso^ =>
    Store(_resp)
  fun ref set(s: String iso) =>
    _resp = s
  fun ref static wait_for_response(conn: TCPConnection iso): String val =>
    var ticks: U64 = 0
    while conn.active() and (ticks < 5000) do
      ticks = ticks + 1
    end
    let n = conn.notify() as ClientNotify
    n.finish()

