    int ret=MHD_queue_response(con,200,resp); MHD_destroy_response(resp); return ret;
  }
  if(strcmp(url,"/health")==0){
    const char *body="{\"status\":\"ok\",\"engine\":\"futhark\"}";
    struct MHD_Response *resp=MHD_create_response_from_buffer(strlen(body),(void*)body,MHD_RESPMEM_PERSISTENT);
