using System;
using System.Net;
using System.Text;
using System.Text.Json;
using System.Threading.Tasks;
class Program
{
    static async Task Main(string[] args)
    {
        var listener = new HttpListener();
        listener.Prefixes.Add("");
        listener.Start();
        while (true)
        {
            var ctx = await listener.GetContextAsync();
            await Handle(ctx);
        }
    }
    static async Task Handle(HttpListenerContext ctx)
    {
        ctx.Response.Headers.Add("Access-Control-Allow-Origin", "*");
        ctx.Response.Headers.Add("Content-Type", "application/json");
        if (ctx.Request.HttpMethod == "OPTIONS")
        {
            ctx.Response.StatusCode = 200;
            ctx.Response.Close();
            return;
        }
        if (ctx.Request.Url.AbsolutePath == "/quantum/molecular")
        {
            using var r = new System.IO.StreamReader(ctx.Request.InputStream);
            var body = await r.ReadToEndAsync();
            var doc = JsonDocument.Parse(body);
            var seq = doc.RootElement.GetProperty("sequence").GetString();
            var n = Math.Min(8, seq.Length);
            var res = new int[n];
            for (int i = 0; i < n; i++) res[i] = ((int)seq[i]) & 1;
            var json = JsonSerializer.Serialize(new { status = "success", quantum_encoded = true, measurements = res });
            var buf = Encoding.UTF8.GetBytes(json);
            ctx.Response.ContentLength64 = buf.Length;
            await ctx.Response.OutputStream.WriteAsync(buf, 0, buf.Length);
            ctx.Response.Close();
            return;
        }
        if (ctx.Request.Url.AbsolutePath == "/health")
        {
            var json = JsonSerializer.Serialize(new { status = "ok" });
            var buf = Encoding.UTF8.GetBytes(json);
            ctx.Response.ContentLength64 = buf.Length;
            await ctx.Response.OutputStream.WriteAsync(buf, 0, buf.Length);
            ctx.Response.Close();
            return;
        }
        ctx.Response.StatusCode = 404;
        ctx.Response.Close();
    }
}

